const SHOPS={}; P.forEach(p=>{if(p.shops)SHOPS[p.id]=p.shops});
function rng(seed){let s=seed>>>0;return()=>{s=(s*1664525+1013904223)>>>0;return s/4294967296}}
function visType(d){
  if(d.st==='N')return'none';
  if(typeof d.val==='string')return'text';
  if(/จำแนก.*อำเภอ/.test(d.n))return'district';
  if(d.u==='บาท')return/มูลค่า/.test(d.n)?'money':'price';
  if(d.u==='ไร่')return'area';
  if(/^(ราย|คน)$/.test(d.u))return'people';
  if(/กก|ตัน|ตัว|ผืน|ชิ้น|หัว|ต้น/.test(d.u)&&d.val>40)return'qty';
  return'count';
}
P.forEach((p,i)=>{
  p.no=p.id; p.code='P'+String(p.id).padStart(2,'0');
  const r=rng(p.id*7919);
  const a={};a[2568]=p.v;a[2567]=p.v/(1+p.gr[1]);a[2566]=a[2567]/(1+p.gr[0]);a[2569]=p.v*(1+p.gr[2]);
  const wsum=p.season.reduce((x,y)=>x+y,0);
  p.m={};
  YEARS.forEach(y=>{p.m[y]=MONTHS.map((_,k)=>{if(y===LAST.y&&k>=LAST.m)return null;return Math.round(a[y]*p.season[k]/wsum*(0.92+r()*0.16))})});
  if(p.real&&p.real.v){const s=p.m[ANCHOR].reduce((x,y)=>x+y,0);p.m[ANCHOR]=p.m[ANCHOR].map(v=>Math.round(v*p.v/s));}
  p.priceY={2566:p.price/1.06,2567:p.price/1.03,2568:p.price,2569:p.price*1.03};
  p.prodY={2566:Math.round(p.prod/1.05),2567:Math.round(p.prod/1.02),2568:p.prod,2569:Math.round(p.prod*1.03)};
  const meta=ROW_META[p.id]||{};
  let seq=[0,0,0];
  p.inds=p.ind.trim().split('\n').map((l,ix)=>{const[s,n,u,st,v]=l.split('|');const sN=+s;seq[sN]++;
    const m=Object.assign({},meta['*']||{},meta[ix+1]||{});
    return{s:sN,n,u,st:st||'',raw:v,row:ix+1,code:`${p.code}-${sN+1}${String(seq[sN]).padStart(2,'0')}`,ag:m.ag||p.agency,per:m.per||'',src:'sim'}});
  p.inds.forEach(d=>{
    if(d.st==='R'){d.val=isNaN(+d.raw)?d.raw:+d.raw;d.src='real';return}
    if(d.st==='N'){d.val=null;d.src='none';return}
    const k=p.sz, u=d.u;
    if(/มูลค่า/.test(d.n)){d.val=Math.round(p.v*(/ส่งออก|นอกจังหวัด/.test(d.n)?.12:/ออนไลน์/.test(d.n)?.18:/ภายใน|ออฟไลน์|ปลาสด/.test(d.n)?.55:/แปรรูป/.test(d.n)?.35:1)/1000)*1000;return}
    if(/ราคา/.test(d.n)){d.val=Math.round(p.price);return}
    if(/ต้นทุน/.test(d.n)){d.val=Math.round((/ไร่|ตัว|รอบ|โรงเรือน/.test(d.n)?3000+r()*4000:/ขนส่ง/.test(d.n)?180+r()*120:20+r()*60)*(p.price>10000?3:1));return}
    if(u==='ไร่'){d.val=Math.round((300+r()*900)*k*(/GAP|รับรอง/.test(d.n)?.2:1)*(/ทุ่งหญ้า|อาหารสัตว์/.test(d.n)?2:1))*10;return}
    if(u==='ราย'||u==='คน'){d.val=/ผู้เพาะ|ผู้ปลูก|ผู้เลี้ยง|ช่างทอ|ผู้เก็บ|ที่ปลูก|เกษตรกรผู้/.test(d.n)?p.prod:Math.round((20+r()*140)*Math.sqrt(k));return}
    if(u==='ตัว'){d.val=Math.round(p.vol*(p.unit==='ตัว'?5.5:1.2));return}
    if(/กก|ตัน|ผืน|ชิ้น|หัว|ต้น/.test(u)){d.val=Math.round(p.vol*(/แปรรูป|คัดเกรด|นำเข้า|เนื้อ|ผลพลอย|พร้อมจำหน่าย|ชิ้นงาน/.test(d.n)?.22+r()*.2:/วัตถุดิบ|เส้น|วัสดุ/.test(d.n)?.6:1));return}
    d.val=Math.max(1,Math.round((2+r()*14)*(k>1?1.6:1)));
  });
  p.inds.forEach(d=>{d.vt=visType(d);
    // ค่าย้อนหลังรายปี (สำหรับกราฟเส้นเล็ก) — จำลองจากอัตราเติบโตของสินค้า
    if(typeof d.val==='number'){d.hist={2568:d.val,2567:d.val/(1+p.gr[1]*(.6+r()*.8)),2566:d.val/(1+p.gr[1])/(1+p.gr[0]*(.6+r()*.8))};
      if(d.vt==='district'){const w=p.dist,ws=w.reduce((x,y)=>x+y,0);d.byDist=w.map(x=>Math.round(d.val*x/ws))}}});
  p.ready=[0,1,2].map(s=>{const L=p.inds.filter(d=>d.s===s);return{n:L.length,ok:L.filter(d=>d.st==='R'||d.st==='H').length,real:L.filter(d=>d.st==='R').length}});
});
