const EN={"1": {"t": "Soft and fragrant from the first pot — rice from the Lam Phu plains", "s": "Grown in paddies ringed by limestone hills, fed by natural streams and harvested in early winter. Milled fresh for every lot: slender, soft grains with a gentle aroma — an everyday rice and a gift people remember.", "hl": ["Freshly milled", "Vacuum packed", "Provincial signature gift"], "prodL": "Rice farmers", "priceU": "THB/kg", "peak": "Harvest Nov–Dec"}, "2": {"t": "Sweet from the field — pure cane sugar and fresh-pressed juice", "s": "Sugarcane is the province’s top-earning crop, with a crushing season from December to April. Beyond the sugar mills, communities make cane sugar blocks and fresh juice, and burn-free green harvesting is promoted for cleaner air.", "hl": ["Burn-free harvest", "Pure cane sugar", "Fresh-pressed juice"], "prodL": "Cane growers", "priceU": "THB/tonne", "peak": "Crushing Dec–Apr"}, "3": {"t": "Show-quality Thai buffalo, breeding stock and graded semen", "s": "Local farms have selected Thai swamp buffalo over generations for fine horns, glossy coats and strong frames. The product is breeding stock, show calves and frozen semen from selected sires, supplied to farms nationwide. Buffalo beauty contests build the province’s reputation.", "hl": ["Show-grade buffalo", "Selected sire semen", "Pedigreed breeding stock"], "prodL": "Farming households", "priceU": "THB/head (breeding)", "peak": "Shows & trading Oct–Jan"}, "4": {"t": "Quality fattened beef, firm and rich, direct from Lam Phu farms", "s": "Fattening farms raise native, Brahman-cross and Wagyu-line cattle on pasture and concentrate feed, processed in standard abattoirs into marbled cuts and sun-dried beef for restaurants and consumers.", "hl": ["Livestock OK certified", "Crossbred & Wagyu-line", "Premium sun-dried beef"], "prodL": "Farming households", "priceU": "THB/head", "peak": "Best prices Mar–Apr & year-end"}, "5": {"t": "Free-range native chicken, firm and sweet — Isan-style grilled", "s": "Pradu Hang Dam and Chee chickens roam free on natural feed. Firm meat and crisp skin make them the base of local grill shops, and community groups also make sun-dried chicken for gifts.", "hl": ["Free-range", "Pradu Hang Dam breed", "GAP farms"], "prodL": "Farming households", "priceU": "THB/kg", "peak": "Peak sales at year-end festivals"}, "6": {"t": "Pla som, sun-dried and dried fish — the original Lam Phu taste", "s": "Fish from local ponds and waters are processed by community groups to home recipes: fermented pla som, sun-dried fish, dried fish and fish chili paste. FDA-registered and vacuum packed for nationwide delivery — ready to fry or grill.", "hl": ["FDA-registered pla som", "Sun-dried & dried fish", "Vacuum packed, ships nationwide"], "prodL": "Fish farmers & processors", "priceU": "THB/kg (processed)", "peak": "Year-round, peaks at festivals"}, "7": {"t": "Fresh every morning, plus bold processed mushroom treats", "s": "Mushroom houses in every district grow oyster, split-gill and straw mushrooms for morning markets; the rest becomes sweet mushroom snacks, mushroom chili paste and mushroom sausage — safe plant protein.", "hl": ["Picked fresh daily", "Chili paste & snacks", "GAP mushroom houses"], "prodL": "Mushroom growers", "priceU": "THB/kg", "peak": "High yield Jun–Sep"}, "8": {"t": "Tender shoots from the dry forest — sweet, crisp, dry season only", "s": "Wild sweet leaf sprouts in the dry season, January to April. Villagers pick young shoots from community forests and nature-like plantings — enjoy them in red-ant-egg soup or curry, or year-round as blanched frozen and dried leaf.", "hl": ["Dry-season only", "Nature-like cultivation", "6 learning centers"], "prodL": "Growers & foragers", "priceU": "THB/kg (fresh + processed)", "peak": "Shoots Jan–Apr"}, "9": {"t": "Sweet Namwa bananas, made into dried bananas and crispy chips", "s": "Bananas grow in every district and fruit year-round. Women’s groups sun-dry them and make chips, banana paste and local sweets — affordable, best-selling souvenirs.", "hl": ["Year-round harvest", "Solar-dried", "FDA & community standards"], "prodL": "Banana growers", "priceU": "THB/kg", "peak": "Harvest year-round"}, "10": {"t": "The provincial fabric, handwoven by more than 500 weavers", "s": "Chanuan Lumphu is Nong Bua Lam Phu’s identity fabric; its patterns evoke the river plains and mountains. Woven by artisans across the province into ready-to-wear, bags, scarves and home décor — workwear for any day and a gift that says Lam Phu.", "hl": ["Provincial identity fabric", "Provincial pattern", "14 certified products"], "prodL": "Weavers & master artisans", "priceU": "THB/piece (avg incl. products)", "peak": "Best sellers Oct–Dec (gift season)"}, "11": {"t": "Lam Phu’s beautiful curcuma — the province’s signature flower", "s": "Usa Lamphu curcuma blooms in the rainy season with pink-red bracts against fresh green leaves. Growers select rhizomes and sell potted plants and fresh stems to plant shops, resorts and collectors of native flowers.", "hl": ["Rainy-season bloom", "Graded rhizomes", "Display-ready pots"], "prodL": "Growers", "priceU": "THB/pot", "peak": "Blooms Jun–Sep"}, "12": {"t": "Coffee from the Lam Phu hills — fresh-roasted, aromatic and smooth", "s": "Coffee cherries are hand-picked on upland plots, dried and roasted by local farmer groups for a fresh roast with soft chocolate notes — ideal for local cafés and a gift for coffee lovers.", "hl": ["Hand-picked", "Roasted locally", "Used by local cafés"], "prodL": "Coffee growers", "priceU": "THB/kg (roasted)", "peak": "Cherry harvest Dec–Feb"}, "13": {"t": "Khla weaving from Si Bun Rueang — strong, glossy, fashion-ready", "s": "Khla reeds grow along the waterways of Si Bun Rueang. Artisans split, dry and weave them into mats, sticky-rice baskets and bags whose natural sheen grows with use — eco-friendly craft for modern fashion, registered as a Geographical Indication (GI).", "hl": ["Geographical Indication (GI)", "100% natural fibre", "Handwoven"], "prodL": "Basket weavers", "priceU": "THB/piece", "peak": "Year-round, best sellers at year-end"}, "14": {"t": "Khit and mudmee in a single cloth — two weaving traditions", "s": "Weavers lift supplementary-weft khit patterns and alternate them with mudmee ikat bands in the same cloth — highly skilled work taking weeks on the loom, dyed with local plant colours. Vivid, dimensional fabric for work and special occasions; a Geographical Indication (GI) product.", "hl": ["Geographical Indication (GI)", "Hand-woven", "Natural dyes"], "prodL": "Weavers", "priceU": "THB/piece", "peak": "Best sellers Oct–Dec (gift season)"}};
